    const hold = holds.get(id);
    if (!hold) return;
    if (hold.timer !== null) view.clearTimeout(hold.timer);
    holds.delete(id);
    if (![...holds.values()].some((other) => other.target === hold.target)) hold.target.classList.remove("is-holding");
  };
  const reset = (): void => {
    for (const id of holds.keys()) clearHold(id);
    suppressed.clear();
  };
