import { ru } from "../ru";
import "./connection.css";

type Connection = { node: HTMLSpanElement; dispose: () => void };
const bindings = new WeakMap<HTMLElement, Connection>();
export const bindConnection = (source: HTMLElement): Connection => {
  const current = bindings.get(source);
  if (current) return current;
  const node = source.ownerDocument.createElement("span");
  node.className = "ui-connection";
  node.dataset.uiConnection = "";
  node.setAttribute("role", "img");
  const sync = (): void => {
    const live = source.dataset.live === "1";
    node.dataset.live = live ? "1" : "0";
    node.setAttribute("aria-label", ru(live ? "connection_live" : "connection_dead"));
  };
  sync();
  const observer = new MutationObserver(sync);
  observer.observe(source, { attributes: true, attributeFilter: ["data-live"] });
  source.prepend(node);
  const binding = { node, dispose: () => { observer.disconnect(); node.remove(); bindings.delete(source); } };
  bindings.set(source, binding);
  return binding;
};
''')
